alter table public.joueur_blessures add column if not exists etape_index int not null default 0;

update public.blessure_protocoles set paliers = $j${"etapes": [{"id": "e1", "titre": "Repos & anti-œdème", "description": "Protection, glace/compression, décharge partielle si Grade III. Mobilisation précoce en amplitude non douloureuse.", "tests": []}, {"id": "e2", "titre": "Mobilité & proprioception", "description": "Amplitude complète, équilibre unipodal yeux ouverts puis fermés, plan instable (coussin, planche).", "tests": [{"id": "t1", "nom": "Équilibre unipodal (Y-balance / SEBT)", "critere": "Symétrie ≥ 90% entre les deux jambes"}]}, {"id": "e3", "titre": "Renforcement (fibulaires, chaîne)", "description": "Renforcement des fibulaires (élastique), du mollet et de la chaîne postérieure, gainage.", "tests": [{"id": "t1", "nom": "Force des fibulaires (dynamomètre / élastique)", "critere": "Symétrique, sans douleur"}]}, {"id": "e4", "titre": "Course en ligne droite", "description": "Marche → jogging → course, sans douleur ni compensation.", "tests": [{"id": "t1", "nom": "Course 10 min continue", "critere": "Sans douleur, sans boiterie"}]}, {"id": "e5", "titre": "Changements de direction & pliométrie", "description": "Sauts bipodaux puis unipodaux, coupes, accélérations/décélérations.", "tests": [{"id": "t1", "nom": "Hop tests (simple, triple, croisé, 6m chronométré)", "critere": "LSI ≥ 90% par rapport au côté sain"}, {"id": "t2", "nom": "505 test (changement de direction)", "critere": "Temps ≤ 10% du temps pré-blessure"}]}, {"id": "e6", "titre": "Réathlétisation spécifique", "description": "Vitesse maximale, gestes techniques du poste, volume d'entraînement complet.", "tests": [{"id": "t1", "nom": "Course en huit (figure-8) à vitesse croissante", "critere": "Sans douleur ni appréhension"}]}, {"id": "e7", "titre": "Retour au contact", "description": "Réintégration du plaquage et du regroupement, strapping / chevillère de soutien les premières semaines si besoin.", "tests": []}]}$j$::jsonb, description = 'Ligaments latéraux de la cheville. Délai indicatif : 1–2 sem. (Grade I), 2–6 sem. (Grade II), 6–12 sem. (Grade III).', updated_at = now() where slug = 'entorse_cheville';
update public.blessure_protocoles set paliers = $j${"etapes": [{"id": "e1", "titre": "Protection & isométrique", "description": "Contractions isométriques sous-douloureuses précoces, mobilité du tronc/bassin, vélo léger sans douleur.", "tests": []}, {"id": "e2", "titre": "Travail de force excentrique", "description": "Nordic hamstring progressif, leg curl / pont fessier en excentrique, montée en charge progressive.", "tests": [{"id": "t1", "nom": "Nordic hamstring (ou équivalent selon le muscle)", "critere": "Force symétrique, sans appréhension ni douleur"}]}, {"id": "e3", "titre": "Course progressive", "description": "Marche → jogging → course jusqu'à 70% VMA, sans douleur.", "tests": [{"id": "t1", "nom": "Jogging 15 min continu", "critere": "Sans douleur"}]}, {"id": "e4", "titre": "Vitesse & longueur musculaire", "description": "Montée en vitesse (70 → 100% VMA), travail en longueur (Askling), changements de direction.", "tests": [{"id": "t1", "nom": "Askling H-test (souplesse active en longueur)", "critere": "Amplitude sans douleur, symétrique"}, {"id": "t2", "nom": "Sprint à 90% de la vitesse max", "critere": "Aucune appréhension"}]}, {"id": "e5", "titre": "Sprint maximal & réathlé", "description": "Sprints répétés à vitesse maximale, accélérations / décélérations.", "tests": [{"id": "t1", "nom": "Sprint à 100%", "critere": "Aucune appréhension, mécanique de course normale"}, {"id": "t2", "nom": "Saut horizontal (broad jump) / triple bond", "critere": "LSI ≥ 90%"}]}, {"id": "e6", "titre": "Réintégration sport-spécifique", "description": "Gestes de contact (plaquage, poussée), volume d'entraînement complet avant match.", "tests": []}]}$j$::jsonb, description = 'Classification inspirée du British Athletics Muscle Injury Classification (BAMIC). Délai indicatif : 1–2 sem. (grade 0-1), 3–5 sem. (grade 2), 6–16 sem. (grade 3-4).', updated_at = now() where slug = 'lesion_musculaire';
update public.blessure_protocoles set paliers = $j${"etapes": [{"id": "e1", "titre": "Contrôle de l'œdème & activation", "description": "Glace, amplitude en zone non douloureuse, activation du quadriceps.", "tests": []}, {"id": "e2", "titre": "Renforcement chaîne fermée", "description": "Squats guidés, presse, fentes, proprioception.", "tests": [{"id": "t1", "nom": "Force quadriceps (dynamomètre)", "critere": "LSI ≥ 90%"}]}, {"id": "e3", "titre": "Course en ligne droite", "description": "Marche → jogging rectiligne sans douleur.", "tests": []}, {"id": "e4", "titre": "Renforcement lourd & pliométrie", "description": "Squat / fentes en charge, sauts bipodaux puis unipodaux.", "tests": [{"id": "t1", "nom": "Hop tests (simple, triple, croisé, 6m)", "critere": "LSI ≥ 90%"}]}, {"id": "e5", "titre": "Changements de direction", "description": "COD sous-maximaux puis maximaux.", "tests": [{"id": "t1", "nom": "Test de laxité en valgus (0° et 30°)", "critere": "Stable, sans douleur"}]}, {"id": "e6", "titre": "Retour au contact", "description": "Contact et changements de direction à pleine intensité.", "tests": []}]}$j$::jsonb, description = 'Ligament collatéral médial. Délai indicatif : 1–3 sem. (Grade I), 3–6 sem. (Grade II), 6–10 sem. (Grade III).', updated_at = now() where slug = 'genou_lcm';
update public.blessure_protocoles set paliers = $j${"etapes": [{"id": "e1", "titre": "Post-op & mobilité", "description": "Récupération de l'extension complète en priorité, contrôle de l'œdème, marche sans boiterie, activation du quadriceps.", "tests": []}, {"id": "e2", "titre": "Renforcement & proprioception", "description": "Chaîne fermée puis ouverte, vélo, natation.", "tests": []}, {"id": "e3", "titre": "Course en ligne droite", "description": "Dès accord médical (souvent ~3 mois), progression de la course.", "tests": []}, {"id": "e4", "titre": "Renforcement lourd & pliométrie de base", "description": "Squat, soulevé, fentes ; sauts bipodaux → unipodaux.", "tests": []}, {"id": "e5", "titre": "Pliométrie avancée & COD sous-maximaux", "description": "Réception de saut contrôlée (valgus), coupes progressives.", "tests": [{"id": "t1", "nom": "Contrôle du valgus dynamique à la réception de saut", "critere": "Alignement genou-pied correct"}]}, {"id": "e6", "titre": "Vitesse & COD maximaux", "description": "Sprint, changements de direction à pleine intensité.", "tests": []}, {"id": "e7", "titre": "Réintégration du contact", "description": "Introduction très progressive du contact.", "tests": []}, {"id": "e8", "titre": "Retour au jeu", "description": "Batterie de tests complète + aval médical + préparation psychologique.", "tests": [{"id": "t1", "nom": "Force quadriceps / ischio (isocinétique)", "critere": "LSI ≥ 90% sur les deux groupes"}, {"id": "t2", "nom": "Batterie de hop tests (simple, triple, croisé, 6m)", "critere": "LSI ≥ 90% sur les 4 tests"}, {"id": "t3", "nom": "Questionnaire de préparation psychologique (type ACL-RSI)", "critere": "Score élevé de confiance"}]}]}$j$::jsonb, description = 'Le plus souvent chirurgical (ligamentoplastie). Délai minimum 9 à 12 mois avant retour au contact — le temps seul ne suffit pas, la décision se fait sur les tests ET la préparation psychologique.', updated_at = now() where slug = 'genou_lca';
update public.blessure_protocoles set paliers = $j${"etapes": [{"id": "e1", "titre": "Protection de la cicatrisation", "description": "Flexion limitée les premières semaines si suture, contrôle de l'œdème.", "tests": []}, {"id": "e2", "titre": "Renforcement chaîne fermée", "description": "Proprioception, sans torsion ni flexion profonde.", "tests": []}, {"id": "e3", "titre": "Course sans torsion", "description": "Jogging rectiligne.", "tests": [{"id": "t1", "nom": "Amplitude articulaire complète", "critere": "Symétrique, sans blocage"}]}, {"id": "e4", "titre": "Flexion profonde & pliométrie", "description": "Squat profond progressif, sauts.", "tests": [{"id": "t1", "nom": "Hop tests (simple, triple, croisé, 6m)", "critere": "LSI ≥ 90%"}]}, {"id": "e5", "titre": "Changements de direction & torsion", "description": "COD et appuis en torsion progressifs.", "tests": []}, {"id": "e6", "titre": "Retour au contact", "description": "Contact et appuis en torsion à pleine intensité.", "tests": []}]}$j$::jsonb, description = 'Selon le type (stable/instable) et le traitement (conservateur, suture, méniscectomie). Délai indicatif : 4–12 sem., plus long après suture.', updated_at = now() where slug = 'genou_menisque';
update public.blessure_protocoles set paliers = $j${"etapes": [{"id": "e1", "titre": "Contrôle de la douleur & mobilité passive", "description": "Immobilisation courte si besoin, mobilisation pendulaire, isométrique sous-douloureux des rotateurs.", "tests": []}, {"id": "e2", "titre": "Renforcement coiffe & scapula", "description": "Élastique en rotation interne/externe, gainage, chaîne cinétique de l'épaule.", "tests": [{"id": "t1", "nom": "Force rotation interne / externe (dynamomètre)", "critere": "LSI ≥ 90%, ratio RE/RI dans la norme"}]}, {"id": "e3", "titre": "Charge lourde & pliométrie du haut du corps", "description": "Développé, tirage, lancer de medecine ball.", "tests": [{"id": "t1", "nom": "CKCUEST (stabilité chaîne fermée membre sup.)", "critere": "Nombre de touches symétrique"}]}, {"id": "e4", "titre": "Gestes techniques sans contact", "description": "Passe, réception, armé du bras.", "tests": [{"id": "t1", "nom": "Test d'appréhension / relocation", "critere": "Négatif"}]}, {"id": "e5", "titre": "Réintégration du plaquage", "description": "Technique (épaule basse, tête placée), intensité progressive.", "tests": []}, {"id": "e6", "titre": "Mêlée / regroupement", "description": "En dernier, pleine charge.", "tests": []}]}$j$::jsonb, description = 'Entorse acromio-claviculaire, luxation gléno-humérale ou lésion de la coiffe. Délai très variable selon la lésion (2 sem. à 6 mois).', updated_at = now() where slug = 'epaule';
update public.blessure_protocoles set paliers = $j${"etapes": [{"id": "e1", "titre": "Immobilisation / protection", "description": "Selon la gravité, glace, contrôle de la douleur.", "tests": []}, {"id": "e2", "titre": "Récupération d'amplitude", "description": "Mobilisations douces.", "tests": []}, {"id": "e3", "titre": "Renforcement de la préhension", "description": "Grip, pronosupination, poignet.", "tests": [{"id": "t1", "nom": "Force de préhension (dynamomètre)", "critere": "LSI ≥ 90%"}]}, {"id": "e4", "titre": "Gestes techniques sans contact", "description": "Passe et réception de ballon à vitesse.", "tests": [{"id": "t1", "nom": "Amplitude articulaire complète", "critere": "Comparable au côté sain, sans douleur"}]}, {"id": "e5", "titre": "Retour au jeu protégé", "description": "Attelle / strapping, réintégration progressive du contact.", "tests": []}]}$j$::jsonb, description = 'Entorse, fracture du scaphoïde, luxation de doigt. Délai indicatif : 1–3 sem. (entorse), 6–12 sem. (fracture).', updated_at = now() where slug = 'poignet_main';
update public.blessure_protocoles set paliers = $j${"etapes": [{"id": "e1", "titre": "Repos relatif (min 24–48h)", "description": "Repos physique et cognitif léger, puis activités de la vie quotidienne dès disparition des symptômes au repos.", "tests": []}, {"id": "e2", "titre": "Activité aérobie légère", "description": "Marche / vélo à faible intensité, sans résistance, sans risque de choc à la tête.", "tests": []}, {"id": "e3", "titre": "Exercices sport-spécifiques", "description": "Course, déplacements, sans contact.", "tests": []}, {"id": "e4", "titre": "Entraînement sans contact", "description": "Passes, changements de direction, renforcement, coordination — toujours sans contact.", "tests": []}, {"id": "e5", "titre": "Entraînement avec contact", "description": "Après feu vert médical, réintégration complète de l'entraînement.", "tests": [{"id": "t1", "nom": "Échelle de symptômes (type SCAT6)", "critere": "Retour à la ligne de base individuelle"}, {"id": "t2", "nom": "Tolérance à l'effort progressif", "critere": "Aucun symptôme déclenché à chaque palier"}]}, {"id": "e6", "titre": "Retour au jeu", "description": "Toutes les étapes franchies sans réapparition de symptômes.", "tests": []}]}$j$::jsonb, description = 'Graduated Return to Play (World Rugby), consensus d''Amsterdam 2022. Chaque étape dure au minimum 24h ; tout retour de symptôme fait reculer d''une étape. Délai minimum réglementaire de 12 jours (élite) et validation par un médecin formé à la commotion.', updated_at = now() where slug = 'commotion';
update public.blessure_protocoles set paliers = $j${"etapes": [{"id": "e1", "titre": "Examen neurologique", "description": "Force, sensibilité et réflexes du membre supérieur ; écarter une atteinte structurelle (imagerie si doute).", "tests": [{"id": "t1", "nom": "Bilan neurologique complet du membre supérieur", "critere": "Force, sensibilité et réflexes normaux et symétriques"}]}, {"id": "e2", "titre": "Mobilité & renforcement cervical léger", "description": "Isométrique des fléchisseurs / extenseurs profonds du cou et de la ceinture scapulaire.", "tests": []}, {"id": "e3", "titre": "Renforcement lourd du cou", "description": "Travail de force du cou en charge, gainage cervical.", "tests": [{"id": "t1", "nom": "Force isométrique du rachis cervical (4 directions)", "critere": "Retour au niveau de force pré-blessure"}]}, {"id": "e4", "titre": "Technique de plaquage / mêlée", "description": "Position de tête, engagement, sans opposition puis contrôlée.", "tests": []}, {"id": "e5", "titre": "Retour au contact", "description": "Réintégration en situation réelle.", "tests": []}]}$j$::jsonb, description = 'Atteinte transitoire du plexus brachial (stinger) ou entorse cervicale simple.', updated_at = now() where slug = 'cervical';
update public.blessure_protocoles set paliers = $j${"etapes": [{"id": "e1", "titre": "Contrôle de la douleur", "description": "Respiration profonde / toux indolores (côtes) ou repos relatif (lombaires).", "tests": []}, {"id": "e2", "titre": "Mobilité & gainage", "description": "Reprise progressive de la mobilité, marche puis jogging léger.", "tests": []}, {"id": "e3", "titre": "Renforcement du tronc", "description": "Gainage, rotation progressive en charge légère.", "tests": []}, {"id": "e4", "titre": "Charge fonctionnelle", "description": "Soulevé, rotation du tronc en charge.", "tests": [{"id": "t1", "nom": "Charge fonctionnelle (soulevé, rotation en charge)", "critere": "Technique correcte, charge proche du niveau pré-blessure"}]}, {"id": "e5", "titre": "Retour au contact", "description": "Gilet de protection possible au retour (côtes), mêlée en dernier.", "tests": []}]}$j$::jsonb, description = 'Contusion / fracture costale ou lombalgie mécanique. Rechercher des signes d''alerte (irradiation dans la jambe, déficit neuro).', updated_at = now() where slug = 'cotes_lombaires';
update public.blessure_protocoles set paliers = $j${"etapes": [{"id": "e1", "titre": "Immobilisation", "description": "Selon prescription médicale, décharge stricte si besoin, contrôle de la douleur.", "tests": []}, {"id": "e2", "titre": "Reprise de la mise en charge", "description": "Progressive selon avis médical / radiologique.", "tests": [{"id": "t1", "nom": "Consolidation confirmée (imagerie)", "critere": "Validée par le médecin"}]}, {"id": "e3", "titre": "Renforcement & réathlé", "description": "Course adaptée à la zone consolidée, renforcement progressif.", "tests": []}, {"id": "e4", "titre": "Retour au contact", "description": "Après consolidation confirmée et accord médical.", "tests": [{"id": "t1", "nom": "Force et amplitude de la zone concernée", "critere": "Comparables au côté sain"}]}]}$j$::jsonb, description = 'Délai lié à la consolidation osseuse, variable selon la zone.', updated_at = now() where slug = 'fracture';

update public.joueur_blessures jb
set etape_index = greatest(0, coalesce(jsonb_array_length((bp.paliers->'etapes')), 1) - 1)
from public.blessure_protocoles bp
where jb.protocole_id = bp.id
  and jb.statut <> 'ok'
  and jb.niveau = 'entrainement_complet';
